@startuml

class Customer {
  + address : string
  + vat_number : string
  + head_office_address : string
}

class Product {
  + name : string
  + stock_level : int
}

class Order {
  + order_date : date
  + payment_date : date
  + delivery_date : date
  + is_paid : boolean
}

class OrderLine {
  + quantity : int
}

class Invoice {
  + invoice_date : date
}

class Shipment {
  + status : ShipmentStatus
}

enum ShipmentStatus {
  Packed
  Shipped
  Received
}

class Delivery {
  + status : string
}

Customer "1" -- "*" Order : places
Customer "1" -- "*" Invoice : receives
Order "1" *-- "1..*" OrderLine : contains
OrderLine "*" -- "1" Product : refers to
Order "1" -- "0..*" Invoice : billed_by
Order "1" -- "0..*" Shipment : split_into
Shipment "*" -- "1..*" OrderLine : contains
Shipment "*" -- "1" Delivery : uses
Delivery "1" -- "*" Shipment : includes

@enduml

